from pathlib import Path
import json,shutil,sys,xml.etree.ElementTree as ET
base=Path(__file__).resolve().parent.parent
verification=json.loads((base/'QA/Verification.json').read_text());assert verification['acceptedTests']>0
sources=[Path(x) for x in sys.argv[1:]]
captures=base/'Captures';captures.mkdir(exist_ok=True)
files=sorted((p for src in sources for p in src.glob('Mechanics_*.png')),key=lambda p:p.name);assert files
assert len({p.name for p in files})==len(files)
for p in files:shutil.copy2(p,captures/p.name)
groups=[('Playtest feedback', [p.name for p in files if any(s in p.name for s in ['Storage_','Recording_'])]),('Five rounds', [p.name for p in files if 'Round_' in p.name]),('Bomb and gem impacts', [p.name for p in files if any(s in p.name for s in ['Bomb_','_Before.png','_After.png','_Legacy.png']) and 'Spark_' not in p.name]),('Spark flight and creation', [p.name for p in files if 'Spark_' in p.name]),('Runic seal layers', [p.name for p in files if 'Seal_' in p.name])]
groups=[(title,paths) for title,paths in groups if paths]
orders={
 'Playtest feedback':['Mechanics_Storage_Win.png','Mechanics_Recording_Win.png','Mechanics_Recording_Loss.png','Mechanics_Storage_Error.png'],
 'Bomb and gem impacts':['Mechanics_Legacy.png','Mechanics_Before.png']+[f'Mechanics_Bomb_{i:02}.png' for i in range(24)]+['Mechanics_After.png'],
 'Runic seal layers':['Mechanics_Seal_Intact.png','Mechanics_Seal_Cracked.png','Mechanics_Seal_Cleared.png']}
groups=[(title,sorted(paths,key=lambda p:orders[title].index(p)) if title in orders else paths) for title,paths in groups]
assert len({p for _,paths in groups for p in paths})==len(files)
manifest=[{'title':title,'files':paths} for title,paths in groups]
(base/'QA/CaptureManifest.json').write_text(json.dumps(manifest,indent=2))
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Gameplay Mechanics R7 · Capture verification</title>
<style>body{margin:0;background:#0b121c;color:#ecddbc;font:17px/1.5 system-ui}main{max-width:1000px;margin:auto;padding:24px}h1{font-size:28px;color:#e4bf78}a{color:#9dd1f0}select,button{font:inherit;background:#172638;color:#f6e7c3;border:1px solid #937644;border-radius:6px;padding:8px;max-width:100%}label{display:block;margin:12px 0}#frame{width:min(100%,576px);display:block;margin:auto;height:auto}.viewport{overflow:auto;margin:16px 0;border:1px solid #54462f}#frame.native{width:576px;max-width:none}#slider{width:100%}.controls{display:flex;gap:10px;flex-wrap:wrap}#caption{overflow-wrap:anywhere}.note{font-size:14px;color:#bbc8d4}details{border-top:1px solid #465266;margin-top:24px;padding-top:12px}code{overflow-wrap:anywhere}</style>
<main><h1>Gameplay Mechanics R7 · Capture verification</h1><p>All 18 mechanics PlayMode tests passed together under the approved verification-only Vulkan run, with screenshots enabled. This review contains COUNT actual Unity captures from the accepted verification runs. Gameplay rules and artwork are unchanged.</p>
<label>Capture group <select id="group"></select></label><div class="controls"><button id="previous">Previous</button><button id="next">Next</button><button id="native" aria-pressed="false">View at native pixels</button></div><label>Frame <input id="slider" type="range" min="0" value="0" step="1" aria-label="Capture frame"></label><p id="caption"></p><div class="viewport"><img id="frame" alt="Actual Unity gameplay capture"></div>
<p class="note">576×1280 Unity renders. Sequences are sampled screenshots, not a playable browser game or a frame-rate measurement. Ratings are automated test inputs, not player feedback.</p>
<details open><summary>Verification result</summary><p>The earlier repeated-render failure was traced through NVIDIA’s OpenGL draw path. The approved <code>--vulkan-verification</code> runner option completed the full suite in one process. The earlier NVIDIA optimization experiment was only a partial mitigation. No project graphics backend, driver installation or system-wide settings were changed.</p><p class="note">Vulkan was authorized only for verification. The default OpenGL failure remains unresolved; normal Editor settings remain unchanged. It is not a driver repair or Android/device acceptance.</p></details>
<details><summary>Next: manual playtesting</summary><p>In Play Mode at Home, choose <b>Legends of Rus → Development → Gameplay Mechanics Sandbox</b>. Play all five rounds without solution witnesses, and optionally rate difficulty, goal clarity and effects. Check for <b>Saved locally</b>; use <b>Save now</b> if retry is needed. Copy location finds the saved checkpoint or most recent export.</p><p>No manual session was found at the start of this pass. Actual player feedback is still required before difficulty adjustments or content expansion.</p></details>
<p><a href="ImplementationReport.md">Implementation report</a> · <a href="QA/Verification.json">Unity evidence</a> · <a href="QA/Scope.json">Scope</a> · <a href="../R6/Gameplay_Mechanics_R6_Review.html">Local session viewer</a></p></main>
<script>const groups=MANIFEST;const group=document.querySelector('#group'),slider=document.querySelector('#slider'),frame=document.querySelector('#frame');let position=0;groups.forEach((g,i)=>{let o=document.createElement('option');o.value=i;o.textContent=g.title;group.append(o)});function show(){const g=groups[+group.value];position=Math.max(0,Math.min(position,g.files.length-1));slider.max=g.files.length-1;slider.value=position;frame.src='Captures/'+g.files[position];document.querySelector('#caption').textContent=`${position+1}/${g.files.length} · ${g.files[position]}`;document.querySelector('#previous').disabled=position===0;document.querySelector('#next').disabled=position===g.files.length-1}group.onchange=()=>{position=0;show()};slider.oninput=()=>{position=+slider.value;show()};document.querySelector('#previous').onclick=()=>{position--;show()};document.querySelector('#next').onclick=()=>{position++;show()};document.querySelector('#native').onclick=e=>{let enabled=frame.classList.toggle('native');e.target.setAttribute('aria-pressed',String(enabled));e.target.textContent=enabled?'Fit to page':'View at native pixels'};show();</script></html>'''
(base/'Gameplay_Mechanics_R7_Review.html').write_text(html.replace('COUNT',str(len(files))).replace('MANIFEST',json.dumps(manifest)))
print('Review captures:',len(files))
